# schematic: L layers of RY-RZ rotations + CNOT ring on n qubits
def hea(circuit, thetas, n, layers):
    p = 0
    for _ in range(layers):
        for q in range(n):
            circuit.ry(thetas[p], q); p += 1
            circuit.rz(thetas[p], q); p += 1
        for q in range(n):
            circuit.cx(q, (q+1) % n)   # entangling ring
    return circuit
